export function retryDelay(attempt, { baseDelay = 10, maxDelay = 1000 } = {}) {
  if (!Number.isInteger(attempt) || attempt <= 0) {
    throw new RangeError('attempt must be a positive integer');
  }
  if (!Number.isFinite(baseDelay) || baseDelay < 0) {
    throw new RangeError('baseDelay must be a finite nonnegative number');
  }
  if (!Number.isFinite(maxDelay) || maxDelay < 0) {
    throw new RangeError('maxDelay must be a finite nonnegative number');
  }
  if (baseDelay === 0) {
    return 0;
  }
  const delay = baseDelay * 2 ** (attempt - 1);
  if (!Number.isFinite(delay)) {
    return maxDelay;
  }
  return Math.min(maxDelay, delay);
}

