import { retryDelay } from './retry-delay.mjs';

function validatePositiveInteger(value, name) {
  if (!Number.isInteger(value) || value <= 0) {
    throw new RangeError(`${name} must be a positive integer`);
  }
}

function validateNonNegativeFinite(value, name) {
  if (!Number.isFinite(value) || value < 0) {
    throw new RangeError(`${name} must be a finite nonnegative number`);
  }
}

export async function runWithRetry(operation, { maxAttempts = 3, baseDelay = 10, maxDelay = 1000, shouldRetry = () => true, sleep = async () => {} } = {}) {
  if (typeof operation !== 'function') {
    throw new TypeError('operation must be a function');
  }
  if (typeof shouldRetry !== 'function') {
    throw new TypeError('shouldRetry must be a function');
  }
  if (typeof sleep !== 'function') {
    throw new TypeError('sleep must be a function');
  }
  validatePositiveInteger(maxAttempts, 'maxAttempts');
  validateNonNegativeFinite(baseDelay, 'baseDelay');
  validateNonNegativeFinite(maxDelay, 'maxDelay');

  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      return await operation(attempt);
    } catch (reason) {
      if (attempt === maxAttempts) {
        throw reason;
      }
      const permitted = await shouldRetry(reason, attempt);
      if (!permitted) {
        throw reason;
      }
      await sleep(retryDelay(attempt, { baseDelay, maxDelay }), attempt + 1);
    }
  }
}

